#!/usr/bin/env python3
"""
Read the dot matrix charts of the Schneider NLQ401 (fonts/src/NLQ401_Charset.png)
and turn them into pe_font tables (core/src/fonts/font_nlq401_*.c).

The chart holds two blocks of 16 characters per line, cell 55.14 px = 1/10":
  top block    NLQ pass 1+2 (dot pitch 4.14 px horizontally, 2.96 px vertically)
  bottom block draft        (dot pitch 7.86 px horizontally, 5.91 px vertically)
Line 0 of each block shows the DIN German national characters, the bottom
block continues with the CPC symbols 0x80..0xFF.

Dots are located as local maxima of the blurred image; every dot is then put
on its lattice position inside the character cell.
"""
import os, sys
import numpy as np
from PIL import Image
from scipy import ndimage

HERE = os.path.dirname(os.path.abspath(__file__))
PNG = os.path.join(HERE, "..", "fonts", "src", "NLQ401_Charset.png")
OUT = os.path.join(HERE, "..", "core", "src", "fonts")

CELL = 55.14
X0 = -1.1
GERMAN = [0xA7, 0xC4, 0xD6, 0xDC, 0xE4, 0xF6, 0xFC, 0xDF]   # § Ä Ö Ü ä ö ü ß


def dots(img):
    # red arrows in the chart mark characters with software descenders: ignore
    a = 255 - np.array(img.convert("RGB")).astype(float).max(axis=2)
    s = ndimage.gaussian_filter(a, 0.8)
    mx = (s == ndimage.maximum_filter(s, size=3)) & (s > 100)
    ys, xs = np.nonzero(mx)
    pts = sorted(zip(ys.tolist(), xs.tolist()))
    out = []                         # merge duplicates (plateaus) closer than 2.5 px
    for y, x in pts:
        if any(abs(y - oy) < 2.6 and abs(x - ox) < 2.6 for oy, ox in out[-40:]):
            continue
        out.append((y, x))
    return out


def codes_for_line(block, line):
    """codes shown in text line `line` of a block (list of 16 or None)"""
    if line == 0:
        return [None] * 8 + GERMAN
    base = 0x20 + 16 * (line - 1)
    return [base + i if base + i <= (0x7F if block == "draft" else 0x7E) or (block == "draft" and base + i <= 0xFF) else None
            for i in range(16)]


def extract_nlq(pts):
    """-> {code: set((col,row))}  col = px column inside the cell, row = 2.96 px lines"""
    P = 2.96
    glyphs = {}
    for line in range(7):
        top = 14 + 65 * line
        band = [(y, x) for y, x in pts if top - 6 <= y < top + 62]
        if not band: continue
        ph = np.angle(np.mean([np.exp(2j * np.pi * y / P) for y, x in band])) / (2 * np.pi) * P
        ref = round((top - ph) / P)
        for code_i, code in enumerate(codes_for_line("nlq", line)):
            if code is None: continue
            xl = X0 + CELL * code_i
            g = set()
            for y, x in band:
                if xl - 0.5 <= x < xl + CELL - 0.5:
                    g.add((int(round(x - xl)), int(round((y - ph) / P)) - ref))
            glyphs[code] = g
    return glyphs


def extract_draft(pts):
    PX, PY = 7.86, 5.91
    glyphs = {}
    # phase of the lattice: the 'H' stems etc. -> use global circular mean
    ys = [y for y, x in pts if y > 520]
    xs = [x for y, x in pts if y > 520]
    phx = np.angle(np.mean([np.exp(2j * np.pi * (x - X0) / PX) for x in xs])) / (2 * np.pi) * PX
    phy = np.angle(np.mean([np.exp(2j * np.pi * y / PY) for y in ys])) / (2 * np.pi) * PY
    for line in range(15):
        top = 529 + 65 * line
        band = [(y, x) for y, x in pts if top - 6 <= y < top + 62]
        ref = round((top - phy) / PY)
        if line < 7:
            codes = codes_for_line("draft", line)
        else:
            codes = [0x80 + 16 * (line - 7) + i for i in range(16)]
        for code_i, code in enumerate(codes):
            if code is None: continue
            xl = X0 + CELL * code_i
            g = set()
            for y, x in band:
                if xl - 0.5 <= x < xl + CELL - 0.5:
                    g.add((int(round((x - xl - phx) / PX)), int(round((y - phy) / PY)) - ref))
            glyphs[code] = g
    return glyphs


def build(glyphs, name, pins_hint, vres, cell, dotsz, lo_col, shift_col=0):
    """column major words; rows are shifted so the topmost used row is 0 for
    the whole font (common offset), baseline = row of the bottom of 'H'."""
    allr = [r for g in glyphs.values() for c, r in g]
    rmin = min(allr)
    rbase = max(r for c, r in glyphs[ord("H")]) - rmin
    pins = max(allr) - rmin + 1
    cmin = min(c for g in glyphs.values() for c, r in g)
    cmax = max(c for g in glyphs.values() for c, r in g)
    off = -min(cmin, 0)
    width = cmax + off + 1
    codes = sorted(glyphs)
    words = []
    for code in codes:
        cols = [0] * width
        for c, r in glyphs[code]:
            cols[c + off] |= 1 << (r - rmin)
        words += cols
    return dict(id=name, pins=pins, width=width, cell=cell, base=rbase, vres=vres,
                dot=dotsz, codes=codes, words=words, off=off)


def emit(f):
    path = os.path.join(OUT, "font_%s.c" % f["id"])
    L = ["/* Generated by tools/pngfont.py from fonts/src/NLQ401_Charset.png -- do not edit. */",
         '#include "pe/font.h"\n',
         "static const uint16_t %s_codes[%d] = {" % (f["id"], len(f["codes"])),
         "    " + ", ".join("0x%02x" % c for c in f["codes"]) + ",\n};\n",
         "static const uint32_t %s_cols[%d] = {" % (f["id"], len(f["words"]))]
    row = []
    for i, w in enumerate(f["words"]):
        row.append("0x%x" % w)
        if (i + 1) % f["width"] == 0:
            L.append("    " + ",".join(row) + ","); row = []
    L.append("};\n")
    L.append("const pe_font pe_font_%s = {" % f["id"])
    L.append('    "%s", %d, %d, %d, %d, %d,' % (f["id"], f["pins"], f["width"], f["cell"], f["base"], len(f["codes"])))
    L.append("    %s_codes, %s_cols, 0, %d, %d," % (f["id"], f["id"], f["vres"], f["dot"]))
    L.append("};")
    open(path, "w").write("\n".join(L) + "\n")


def preview(f, path, text_codes):
    sx, sy = 2, 3
    W = f["width"]; px = []
    img = Image.new("L", (len(text_codes) * f["cell"] * sx + 10, f["pins"] * sy + 6), 255)
    p = img.load()
    for i, code in enumerate(text_codes):
        if code not in f["codes"]: continue
        k = f["codes"].index(code)
        for c in range(W):
            w = f["words"][k * W + c]
            for r in range(f["pins"]):
                if w >> r & 1:
                    for a in range(sx):
                        for b in range(sy):
                            xx = i * f["cell"] * sx + (c - f["off"]) * sx + a + 4
                            yy = r * sy + b + 2
                            if 0 <= xx < img.width and 0 <= yy < img.height: p[xx, yy] = 0
    img.save(path)


def main():
    img = Image.open(PNG)
    pts = dots(img)
    nlq = extract_nlq([q for q in pts if q[0] < 480])
    drf = extract_draft([q for q in pts if q[0] >= 500])
    drf = {c: g for c, g in drf.items() if c < 0x7F or c in GERMAN}   # CPC symbols are not Latin-1
    # 1 px column = 1/551 in, cell = 55 px = 10 cpi;  rows 1/144 in;  dot 3.6 px
    f_nlq = build(nlq, "nlq401_nlq", 0, 144, 55, 17, 0)
    # draft: lattice columns, cell = 7 dots; rows 1/ (5.91px)
    f_drf = build(drf, "nlq401_draft", 0, 72, 7, 22, 0)
    for f in (f_nlq, f_drf): emit(f)
    s = "Das Schneider NLQ401 druckt Hamburgefonts: gjpqy"
    preview(f_nlq, "/tmp/cmp/prev_nlq.png", [ord(c) for c in s])
    preview(f_drf, "/tmp/cmp/prev_drf.png", [ord(c) for c in s])
    print("nlq: %d glyphs, %d wires, %d cols, base %d" % (len(f_nlq["codes"]), f_nlq["pins"], f_nlq["width"], f_nlq["base"]))
    print("draft: %d glyphs, %d wires, %d cols, base %d" % (len(f_drf["codes"]), f_drf["pins"], f_drf["width"], f_drf["base"]))


if __name__ == "__main__":
    main()
